<script setup lang="ts">
import { getRunner } from '~/data/runners'; import { trailRoutes } from '~/data/routes'
const pageRoute=useRoute(); const runner=computed(()=>getRunner(pageRoute.params.slug as string)); if(!runner.value) throw createError({statusCode:404,statusMessage:'Tekač ni najden'})
const favourites=computed(()=>trailRoutes.filter(r=>runner.value?.favouriteRouteSlugs.includes(r.slug)))
useSiteSeo(()=>runner.value?.name,()=>runner.value?.bio)
</script>
<template><div v-if="runner" class="detail-page"><header class="runner-hero shell"><div class="runner-portrait"><img :src="runner.image" :alt="`Atmosferski placeholder za profil ${runner.name}`"></div><div><p class="eyebrow">{{ runner.location }} · demo profil</p><h1>{{ runner.name }}</h1><p class="runner-intro">{{ runner.bio }}</p><dl class="runner-facts"><div><dt>Najljubša razdalja</dt><dd>{{ runner.favouriteDistance }}</dd></div><div><dt>Družbena omrežja</dt><dd>Instagram / Strava — kmalu</dd></div></dl><blockquote>“{{ runner.quote }}”</blockquote></div></header><section class="detail-section shell"><SectionHead eyebrow="Iz prve roke" title="Moje tri najljubše trase"/><div class="favourite-routes"><article v-for="(item,index) in favourites" :key="item.id"><div><span class="mono">0{{ index+1 }}</span><p class="eyebrow">{{ item.region }}</p><h3>{{ item.name }}</h3><p>“{{ item.quote }}”</p><NuxtLink :to="`/routes/${item.slug}`" class="text-link">Razišči traso ↗</NuxtLink></div><div><RouteVisual :variant="index+1"/><ElevationProfile compact/><div class="inline-meta mono"><span>{{ item.distance.toLocaleString('sl-SI') }} KM</span><span>{{ item.elevationGain.toLocaleString('sl-SI') }} M+</span></div></div></article></div></section></div></template>
